#!/usr/bin/env bash
# Production-like smoke test: Węglarka starts from the arguments generated by
# `weglarka-daemon platform run-args` (same hardening and env as the quadlet), and
# weglarka.toml has NO `runtime.socket` — the socket comes from the quadlet's env (the image has no /etc/passwd).
#
#   smoke-quadlet.sh <image> <weglarka-binary> <weglarka-daemon-binary> <podman-socket>
set -euo pipefail

image=$1
cli=$2
daemon=$3
podman_sock=$4 # kept for the CI call signature; the socket is resolved by the daemon on the host
: "$podman_sock"

dir=$(mktemp -d -p "${RUNNER_TEMP:-$HOME}") # not under /tmp: the container has a tmpfs there
chmod 755 "$dir"
admin_sock="$dir/run/admin.sock"
mkdir -p "$dir/run" # the operator creates the admin socket dir (docs/install.md)
touch "$dir/traefik.yml"

cat > "$dir/weglarka.toml" <<TOML
[runtime]
user = "$(id -un)"
# deliberately no socket — the production scenario

[ingress]
mode = "behind"
bind = "127.0.0.1:18081"
traefik_dynamic_file = "$dir/traefik.yml"
nginx_image = "docker.io/library/nginx:1.31.8-alpine@sha256:1ef7ca94d7879df82421428ce13bd1eaa412404953859cf7a5b6512c25e67a60"

[state]
dir = "$dir"

[admin]
socket = "$admin_sock"

[webhook]
listen = "0.0.0.0:9180"
domain = "weglarka.example.test"
TOML

cleanup() {
  status=$?
  echo "::group::weglarka logs"; podman logs weglarka 2>&1 || true; echo "::endgroup::"
  echo "::group::weglarka-nginx logs"; podman logs weglarka-nginx 2>&1 || true; echo "::endgroup::"
  podman rm -f weglarka weglarka-nginx >/dev/null 2>&1 || true
  podman network rm -f net-weglarka >/dev/null 2>&1 || true
  exit "$status"
}
trap cleanup EXIT

# The host resolves the Podman socket (as platform install does); the quadlet creates the network from its .network file.
export XDG_RUNTIME_DIR=${XDG_RUNTIME_DIR:-/run/user/$(id -u)}
mapfile -t args < <("$daemon" --config "$dir/weglarka.toml" platform run-args --image "$image" 2>/dev/null)
printf '%s\n' "podman run -d --pull=never ${args[*]}"
podman network create net-weglarka >/dev/null 2>&1 || true
podman run -d --pull=never "${args[@]}"

echo "waiting for admin socket"
for _ in $(seq 30); do [ -S "$admin_sock" ] && break; sleep 1; done
[ -S "$admin_sock" ] || { echo "admin socket did not appear"; podman ps -a; exit 1; }

"$cli" --socket "$admin_sock" status

echo "waiting for nginx container"
for _ in $(seq 90); do
  [ "$(podman inspect -f '{{.State.Running}}' weglarka-nginx 2>/dev/null || true)" = true ] && break
  sleep 1
done
[ "$(podman inspect -f '{{.State.Running}}' weglarka-nginx 2>/dev/null || true)" = true ] \
  || { echo "nginx container is not running"; exit 1; }

# Hardening is actually applied.
[ "$(podman inspect -f '{{.HostConfig.ReadonlyRootfs}}' weglarka)" = true ] || { echo "rootfs not read-only"; exit 1; }
[ "$(podman inspect -f '{{.HostConfig.Memory}}' weglarka)" -gt 0 ] || { echo "no memory limit"; exit 1; }
[ "$(podman inspect -f '{{.State.Running}}' weglarka)" = true ] || { echo "weglarka not running"; exit 1; }
# The ingress nginx is hardened too (docs/decisions/0014) — same checks as in smoke-image.sh.
[ "$(podman inspect -f '{{.HostConfig.ReadonlyRootfs}}' weglarka-nginx)" = true ] \
  || { echo "weglarka-nginx rootfs is not read-only"; exit 1; }
podman inspect -f '{{.HostConfig.SecurityOpt}}' weglarka-nginx | grep -q 'no-new-privileges' \
  || { echo "weglarka-nginx runs without no-new-privileges"; exit 1; }
caps=$(podman inspect -f '{{json .EffectiveCaps}}' weglarka-nginx)
[ "$(printf '%s' "$caps" | grep -o 'CAP_[A-Z_]*' | sort -u | tr '\n' ' ' || true)" = "CAP_CHOWN CAP_SETGID CAP_SETUID " ] \
  || { echo "weglarka-nginx capabilities are not exactly CHOWN+SETGID+SETUID: $caps"; exit 1; }
podman exec weglarka-nginx nginx -t -c /etc/nginx/nginx.conf \
  || { echo "nginx -t fails inside the hardened container"; exit 1; }
echo "weglarka-nginx is hardened: read-only root, no-new-privileges, CHOWN+SETGID+SETUID only"
[ -s "$dir/traefik.yml" ] || { echo "traefik file not written"; exit 1; }
[ -s "$dir/nginx/nginx.conf" ] || { echo "nginx.conf not written"; exit 1; }
echo "OK"
